/**
 * @distilled.cloud/axiom -- Axiom SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the three OpenAPI specs in
 * specs/docs/restapi/versions. Everything else in this folder is hand-written.
 *
 * The v2 control-plane operations are on the package root; the v1 edge APIs
 * are under their own subpath imports. The v2 operations the spec marks
 * `x-axiom-preview` (datasets, monitors, notifiers, users) are generated to
 * `./unstable-services` and imported as `@distilled.cloud/axiom/unstable/v2`:
 *
 * @example
 * ```ts
 * import * as Axiom from "@distilled.cloud/axiom";
 * import * as AxiomPreview from "@distilled.cloud/axiom/unstable/v2";
 * import * as EdgeIngest from "@distilled.cloud/axiom/edge-ingest";
 * import * as EdgeQuery from "@distilled.cloud/axiom/edge-query";
 *
 * const dashboards = yield* Axiom.listDashboards({});
 * const datasets = yield* AxiomPreview.getDatasets({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { AxiomProtocol, stripNulls, type AxiomOpError, type AxiomOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
// v0-parity surface: the v2 control-plane operations live on the package
// root (edge-ingest / edge-query stay behind their subpath exports).
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the ops actually raise the service-local classes.
export * from "./services/v2.ts";
export { BadRequest, Conflict, Forbidden, NotFound, UnprocessableEntity } from "./services/v2.ts";
